package com.rustyledger.impl;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

public class TransactionStore {
    public static class Transaction {
        public String id, verb, date, fromId, toId, currency;
        public BigDecimal amount, fee, credited;
        public boolean reversed;
        public Transaction(String id, String v, String d, String f, String t, BigDecimal a, String c, BigDecimal fe, BigDecimal cr) {
            this.id = id; this.verb = v; this.date = d; this.fromId = f; this.toId = t;
            this.amount = a; this.currency = c; this.fee = fe; this.credited = cr;
            this.reversed = false;
        }
    }

    private final Map<String, Transaction> txs = new LinkedHashMap<>();
    private int txSeq = 0;

    public String nextId() {
        return String.format("TX-%06d", ++txSeq);
    }

    public void save(Transaction tx) {
        txs.put(tx.id, tx);
    }

    public Transaction get(String id) {
        return txs.get(id);
    }
}

