package com.rustyledger.impl;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class ReportStore {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void count(String date, int slot) {
        counts.computeIfAbsent(date, k -> new int[2])[slot]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.merge(currency, delta, BigDecimal::add);
    }

    public String generate(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rej = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String ft = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            f.forEach((cur, val) -> {
                if (sb.length() > 0) sb.append(", ");
                sb.append(val).append(" ").append(cur);
            });
            ft = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rej + "\nfees: " + ft;
    }
}

package com.rustyledger.impl;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyConverter {
    public BigDecimal getRate(String currency) {
        if ("EUR".equals(currency)) return new BigDecimal("4.30");
        if ("USD".equals(currency)) return new BigDecimal("4.00");
        return new BigDecimal("1.00");
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(getRate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(getRate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger.impl;

public class InstructionParser {
    public static class Parsed {
        public String verb, date, from, to, amount, currency, txId;
        public int want;
    }

    public Parsed parse(String line) {
        if (line == null || line.trim().isEmpty()) return null;
        String[] f = line.split("\\|", -1);
        Parsed p = new Parsed();
        p.verb = f[0];
        p.want = switch (p.verb) {
            case "TRANSFER" -> 6;
            case "WITHDRAW", "DEPOSIT" -> 4;
            case "REVERSE" -> 3;
            default -> -1;
        };
        if (p.want == -1) return p;
        if (f.length != p.want) return p;
        p.date = f[1];
        if (!p.date.matches("\\d{4}-\\d{2}-\\d{2}")) return p;
        if ("TRANSFER".equals(p.verb)) {
            p.from = f[2]; p.to = f[3]; p.amount = f[4]; p.currency = f[5];
        } else if ("WITHDRAW".equals(p.verb) || "DEPOSIT".equals(p.verb)) {
            p.from = f[2]; p.amount = f[3];
        } else if ("REVERSE".equals(p.verb)) {
            p.txId = f[2];
        }
        return p;
    }
}

package com.rustyledger.impl;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class ExecutionEngine {
    private final AccountStore accounts;
    private final TransactionStore txs;
    private final CurrencyConverter conv;

    public ExecutionEngine(AccountStore a, TransactionStore t, CurrencyConverter c) {
        this.accounts = a; this.txs = t; this.conv = c;
    }

    public String validateTransfer(String date, String fromId, String toId, BigDecimal amount, String currency) {
        AccountStore.Account from = accounts.get(fromId);
        if (from == null) return "UNKNOWN_ACCOUNT: " + fromId;
        AccountStore.Account to = accounts.get(toId);
        if (to == null) return "UNKNOWN_ACCOUNT: " + toId;
        if (fromId.equals(toId)) return "SAME_ACCOUNT: cannot transfer to the same account";
        if (!from.currency.equals(currency)) return "CURRENCY_MISMATCH: " + fromId + " holds " + from.currency;
        BigDecimal fee = calcTransferFee(from.tier, amount);
        String lim = checkLimitAndFunds(date, fromId, from, amount, fee);
        return lim;
    }

    private BigDecimal calcTransferFee(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            return amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.20"));
        } else if ("PREMIUM".equals(tier)) {
            return amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return new BigDecimal("0.00");
    }

    public String checkLimitAndFunds(String date, String id, AccountStore.Account a, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit, overdraft = BigDecimal.ZERO;
        if ("STANDARD".equals(a.tier)) limit = new BigDecimal("5000.00");
        else if ("PREMIUM".equals(a.tier)) { limit = new BigDecimal("20000.00"); overdraft = new BigDecimal("500.00"); }
        else limit = new BigDecimal("50000.00");
        // Note: 'used' map logic is handled in LedgerImpl to keep this clean
        return null; // Logic moved to LedgerImpl for simplicity in this split
    }

    public BigDecimal getWithdrawFee(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("1.00") : BigDecimal.ZERO;
    }
}

package com.rustyledger.impl;

import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.util.*;

public class LedgerImpl implements Ledger {
    private final AccountStore accounts = new AccountStore();
    private final TransactionStore txs = new TransactionStore();
    private final AuditStore audit = new AuditStore();
    private final ReportStore report = new ReportStore();
    private final CurrencyConverter conv = new CurrencyConverter();
    private final InstructionParser parser = new InstructionParser();
    private final ExecutionEngine engine = new ExecutionEngine(accounts, txs, conv);
    private final Map<String, BigDecimal> used = new HashMap<>();

    public void openAccount(String id, String tier, String currency, String bal) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) throw new IllegalArgumentException();
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException();
        if (!Set.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException();
        if (bal == null || !bal.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException();
        if (accounts.exists(id)) throw new IllegalStateException();
        accounts.open(id, tier, currency, new BigDecimal(bal).setScale(2));
    }

    public String balance(String id) {
        AccountStore.Account a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException();
        return a.balance + " " + a.currency;
    }

    public List<String> auditLog() { return audit.getLog(); }
    public String dailyReport(String date) { return report.generate(date); }

    public String submit(String line) {
        InstructionParser.Parsed p = parser.parse(line);
        if (p == null) return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        if (p.want == -1) return reject(p.verb, null, "BAD_INSTRUCTION", "unknown verb " + p.verb);
        if (p.want != -1 && p.want != (line == null ? 0 : line.split("\\|", -1).length)) 
            return reject(p.verb, null, "BAD_INSTRUCTION", p.verb + " needs " + p.want + " fields");
        if (p.date == null) return reject(p.verb, null, "BAD_DATE", "???"); // simplified for brevity
        if ("REVERSE".equals(p.verb)) return doReverse(p.date, p.txId);
        BigDecimal amount = parseAmount(p.amount);
        if (amount == null) return reject(p.verb, p.date, "BAD_AMOUNT", p.amount);
        if ("TRANSFER".equals(p.verb)) return doTransfer(p.date, p.from, p.to, amount, p.currency);
        if ("WITHDRAW".equals(p.verb)) return doWithdraw(p.date, p.from, amount);
        return doDeposit(p.date, p.from, amount);
    }

    private BigDecimal parseAmount(String s) {
        if (s == null || !s.matches("\\d+(\\.\\d{1,2})?") || new BigDecimal(s).signum() <= 0) return null;
        return new BigDecimal(s).setScale(2);
    }

    private String doTransfer(String date, String fromId, String toId, BigDecimal amount, String currency) {
        String rej = engine.validateTransfer(date, fromId, toId, amount, currency);
        if (rej != null) return reject("TRANSFER", date, rej.split(":")[0], rej.split(":")[1].trim());
        AccountStore.Account from = accounts.get(fromId);
        AccountStore.Account to = accounts.get(toId);
        BigDecimal fee = engine.calcTransferFee(from.tier, amount);
        if (isLimitExceeded(date, fromId, from, amount, fee)) 
            return reject("TRANSFER", date, "LIMIT_EXCEEDED", "daily limit " + getLimit(from.tier) + " for " + from.tier);
        if (from.balance.subtract(amount.add(fee)).compareTo(getOverdraft(from.tier).negate()) < 0)
            return reject("TRANSFER", date, "INSUFFICIENT_FUNDS", "balance " + from.balance + " " + from.currency + ", needed " + amount.add(fee) + " " + from.currency);

        BigDecimal credited = from.currency.equals(to.currency) ? amount : conv.convert(amount, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amount.add(fee));
        to.balance = to.balance.add(credited);
        used.put(fromId + "|" + date, used.getOrDefault(fromId + "|" + date, BigDecimal.ZERO).add(amount));
        String txId = txs.nextId();
        txs.save(new TransactionStore.Transaction(txId, "TRANSFER", date, fromId, toId, amount, from.currency, fee, credited));
        report.addFee(date, from.currency, fee);
        return accept("TRANSFER", date, txId, "fee=" + fee + " " + from.currency);
    }

    private String doWithdraw(String date, String id, BigDecimal amount) {
        AccountStore.Account a = accounts.get(id);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = engine.getWithdrawFee(a.tier);
        if (isLimitExceeded(date, id, a, amount, fee)) 
            return reject("WITHDRAW", date, "LIMIT_EXCEEDED", "daily limit " + getLimit(a.tier) + " for " + a.tier);
        if (a.balance.subtract(amount.add(fee)).compareTo(getOverdraft(a.tier).negate()) < 0)
            return reject("WITHDRAW", date, "INSUFFICIENT_FUNDS", "balance " + a.balance + " " + a.currency + ", needed " + amount.add(fee) + " " + a.currency);
        a.balance = a.balance.subtract(amount.add(fee));
        used.put(id + "|" + date, used.getOrDefault(id + "|" + date, BigDecimal.ZERO).add(amount));
        String txId = txs.nextId();
        txs.save(new TransactionStore.Transaction(txId, "WITHDRAW", date, id, "", amount, a.currency, fee, amount));
        report.addFee(date, a.currency, fee);
        return accept("WITHDRAW", date, txId, "fee=" + fee + " " + a.currency);
    }

    private String doDeposit(String date, String id, BigDecimal amount) {
        AccountStore.Account a = accounts.get(id);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        a.balance = a.balance.add(amount);
        String txId = txs.nextId();
        txs.save(new TransactionStore.Transaction(txId, "DEPOSIT", date, id, "", amount, a.currency, BigDecimal.ZERO, amount));
        return accept("DEPOSIT", date, txId, "fee=0.00 " + a.currency);
    }

    private String doReverse(String date, String txId) {
        TransactionStore.Transaction tx = txs.get(txId);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", txId);
        if (!"TRANSFER".equals(tx.verb)) return reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx.verb);
        if (tx.reversed) return reject("REVERSE", date, "ALREADY_REVERSED", txId);
        if (!tx.date.equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx.date);
        AccountStore.Account from = accounts.get(tx.fromId);
        AccountStore.Account to = accounts.get(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if ("PREMIUM".equals(from.tier)) {
            back = back.add(tx.fee);
            report.addFee(date, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        tx.reversed = true;
        String newId = txs.nextId();
        txs.save(new TransactionStore.Transaction(newId, "REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited));
        return accept("REVERSE", date, newId, "reversed " + txId);
    }

    private boolean isLimitExceeded(String date, String id, AccountStore.Account a, BigDecimal amount, BigDecimal fee) {
        return used.getOrDefault(id + "|" + date, BigDecimal.ZERO).add(amount).compareTo(getLimit(a.tier)) > 0;
    }
    private BigDecimal getLimit(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("5000.00") : "PREMIUM".equals(tier) ? new BigDecimal("20000.00") : new BigDecimal("50000.00");
    }
    private BigDecimal getOverdraft(String tier) {
        return "PREMIUM".equals(tier) ? new BigDecimal("500.00") : BigDecimal.ZERO;
    }
    private String accept(String v, String d, String tid, String e) {
        report.count(d, 0); audit.record(v, d, "OK " + tid);
        return "OK " + tid + " " + e;
    }
    private String reject(String v, String d, String c, String m) {
        if (d != null) report.count(d, 1);
        audit.record(v, d == null ? "????-??-??" : d, "REJECTED " + c);
        return "REJECTED " + c + ": " + m;
    }
}

